import java.util.*;
import java.io.*;

public class fivedimpoints {
    static int n;
    static int[][] coord;
    static long[][][] vect;
    static boolean[] bad;

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }
        coord = new int[n][5];
        vect = new long[n][n][5];
        bad = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                coord[i][j] = scanner.nextInt();
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 5; k++) {
                    vect[i][j][k] = coord[j][k] - coord[i][k];
                }
            }
        }
        int count = n;
        long prod;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j != i) {
                    for (int k = 0; k < n; k++) {
                        if (k != j && k != i) {
                            prod = 0;
                            for (int m = 0; m < 5; m++) {
                                prod += vect[j][i][m] * vect[k][i][m];
                            }
                            if (prod > 0 && !bad[i]) {
                                bad[i] = true;
                                count--;
                            }
                        }
                    }
                }
            }
        }
        System.out.println(count);
        for (int i = 0; i < n; i++) {
            if (!bad[i]) {
                System.out.println(i + 1);
            }
        }
        scanner.close();
    }
}
